/* Minimal localnet client: BLS keys, signing, tx submit and lookups (M0 spike; M2 game messages) */

import { createHash, randomBytes } from 'crypto';
import { createRequire } from 'module';
import { bls12_381 } from '@noble/curves/bls12-381.js';

const require = createRequire(import.meta.url);
// generated by the plugin build; shared so client and plugin encode identically
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const protoRoot: any = require(process.env.ABBEY_PROTO || '../../../plugin/src/proto/index.cjs');
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const types: any = protoRoot.types;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const google: any = protoRoot.google;

// node port block (500 = root chain node, 300 = nested chain node) and target chain id
const PORT = process.env.PORT || '500';
export const RPC = `http://127.0.0.1:${PORT}02`;
export const ADMIN = `http://127.0.0.1:${PORT}03`;
export const PLUGIN_RPC = 'http://127.0.0.1:50010';
export const NETWORK_ID = BigInt(process.env.NETWORK_ID || 1);
export const CHAIN_ID = BigInt(process.env.CHAIN_ID || 1);
export const TREASURY = sha256hex(Buffer.from('abbey.treasury.v1')).slice(0, 40);
export const FAUCET = sha256hex(Buffer.from('abbey.faucet.v1')).slice(0, 40);

export interface Key {
    address: string;
    publicKey: string;
    privateKey: string;
}

// local-only keystore password for throwaway test accounts, generated per run
const KEY_PASSWORD = randomBytes(12).toString('hex');

// cap in-flight HTTP requests: a single node's RPC resets connections at ~1k req/s bursts
const MAX_IN_FLIGHT = Number(process.env.MAX_IN_FLIGHT || 32);
let inFlight = 0;
const waiters: (() => void)[] = [];

async function withSlot<T>(fn: () => Promise<T>): Promise<T> {
    while (inFlight >= MAX_IN_FLIGHT) {
        await new Promise<void>((r) => waiters.push(r));
    }
    inFlight++;
    try {
        return await fn();
    } finally {
        inFlight--;
        waiters.shift()?.();
    }
}

export async function post(url: string, body: unknown): Promise<any> {
    return retry(() => withSlot(() => postOnce(url, body)), 4, (e) => !String(e).includes(' 4'));
}

async function postOnce(url: string, body: unknown): Promise<any> {
    const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
    });
    const text = await res.text();
    if (!res.ok) {
        throw new Error(`${url} ${res.status}: ${text}`);
    }
    return text ? JSON.parse(text) : null;
}

export async function get(url: string): Promise<{ status: number; body: any }> {
    const res = await fetch(url);
    return { status: res.status, body: await res.json() };
}

// newKey() creates a throwaway key in the localnet node's keystore and returns it
export async function newKey(nickname: string): Promise<Key> {
    const address = await retry(() => post(`${ADMIN}/v1/admin/keystore-new-key`, { nickname, password: KEY_PASSWORD }));
    const k = await retry(() => post(`${ADMIN}/v1/admin/keystore-get`, { address, password: KEY_PASSWORD }));
    return {
        address: k.address || k.Address || address,
        publicKey: k.publicKey || k.PublicKey || k.public_key,
        privateKey: k.privateKey || k.PrivateKey || k.private_key
    };
}

// localKey() generates a throwaway BLS key in memory; address = sha256(pubkey)[:20] (lib/crypto/bls.go)
export function localKey(): Key {
    const priv = bls12_381.utils.randomSecretKey();
    const pub = bls12_381.longSignatures.getPublicKey(priv).toBytes(true);
    return {
        address: sha256(pub).subarray(0, 20).toString('hex'),
        publicKey: Buffer.from(pub).toString('hex'),
        privateKey: Buffer.from(priv).toString('hex')
    };
}

// retry() retries transport failures (the admin keystore endpoint resets connections under bursts)
async function retry<T>(fn: () => Promise<T>, attempts = 5, retryable: (e: unknown) => boolean = () => true): Promise<T> {
    for (let i = 1; ; i++) {
        try {
            return await fn();
        } catch (e) {
            if (i >= attempts || !retryable(e)) throw e;
            await sleep(500 * i);
        }
    }
}

export async function height(): Promise<bigint> {
    return BigInt((await post(`${RPC}/v1/query/height`, {})).height);
}

export async function balance(address: string): Promise<bigint> {
    const acc = await post(`${RPC}/v1/query/account`, { address });
    return BigInt(acc?.amount ?? 0);
}

export async function feePool(): Promise<bigint> {
    const pool = await post(`${RPC}/v1/query/pool`, { id: Number(CHAIN_ID) });
    return BigInt(pool?.amount ?? 0);
}

export async function block(h: bigint): Promise<any> {
    return post(`${RPC}/v1/query/block-by-height`, { height: Number(h) });
}

// message type -> [proto message name, field encoder for JSON transport]
const MESSAGES: Record<string, string> = {
    send: 'MessageSend',
    faucet_claim: 'MessageFaucetClaim',
    set_params: 'MessageSetParams',
    create_character: 'MessageCreateCharacter',
    assign_stats: 'MessageAssignStats',
    enter_dungeon: 'MessageEnterDungeon',
    act: 'MessageAct',
    reveal: 'MessageReveal',
    give: 'MessageGive',
    extract: 'MessageExtract',
    shop_buy: 'MessageShopBuy',
    shop_sell: 'MessageShopSell',
    stash_move: 'MessageStashMove'
};

/** bytes fields are Uint8Array (signed as raw bytes, sent to the RPC as hex); everything else as-is */
export type MsgFields = Record<string, Uint8Array | string | number | boolean | number[]>;

// submit() builds, signs and broadcasts a tx
export async function submit(key: Key, msgType: string, fields: MsgFields, fee: bigint): Promise<string> {
    const name = MESSAGES[msgType];
    const typeUrl = `type.googleapis.com/types.${name}`;
    const protoFields: Record<string, unknown> = {};
    const msgJSON: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(omitDefaults(fields as Record<string, unknown>))) {
        protoFields[k] = v instanceof Uint8Array ? Buffer.from(v) : v;
        msgJSON[k] = v instanceof Uint8Array ? Buffer.from(v).toString('hex') : v;
    }
    const msgBytes = types[name].encode(types[name].create(omitDefaults(protoFields))).finish();
    const created = await height();
    const time = BigInt(Date.now()) * 1000n;
    const unsigned = types.Transaction.create(omitDefaults({
        messageType: msgType,
        msg: google.protobuf.Any.create({ type_url: typeUrl, value: msgBytes }),
        createdHeight: Number(created),
        time: Number(time),
        fee: Number(fee),
        networkId: Number(NETWORK_ID),
        chainId: Number(CHAIN_ID)
    }));
    const signBytes = types.Transaction.encode(unsigned).finish();
    const point = bls12_381.longSignatures.hash(signBytes);
    const sig = bls12_381.longSignatures.sign(point, Buffer.from(key.privateKey, 'hex'));
    const tx = {
        type: msgType,
        msg: msgJSON,
        signature: {
            publicKey: key.publicKey,
            signature: Buffer.from(bls12_381.longSignatures.Signature.toBytes(sig)).toString('hex')
        },
        time: Number(time),
        createdHeight: Number(created),
        fee: Number(fee),
        memo: '',
        networkID: Number(NETWORK_ID),
        chainID: Number(CHAIN_ID)
    };
    return post(`${RPC}/v1/tx`, tx);
}

// omitDefaults() drops proto3 zero values: protobufjs encodes explicitly-set zeros (fee: 0, nonce: 0)
// but Go omits them, and a single extra field makes the signed bytes differ from what the core verifies
function omitDefaults(fields: Record<string, unknown>): Record<string, unknown> {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(fields)) {
        if (v === 0 || v === 0n || v === '' || v === false || v === null || v === undefined) continue;
        if ((v instanceof Uint8Array || Array.isArray(v)) && v.length === 0) continue;
        out[k] = v;
    }
    return out;
}

// waitTx() polls until the tx is committed (returns its result) or failed (throws)
export async function waitTx(hash: string, sender: string, timeoutMs = 60_000): Promise<any> {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
        try {
            // tx-by-hash also returns mempool txs stamped with the *next* height, and /query/height
            // reports the next height too, so a tx is committed only once its height is below it
            const tx = await post(`${RPC}/v1/query/tx-by-hash`, { hash });
            if (tx && tx.height && BigInt(tx.height) < (await height())) {
                return tx;
            }
        } catch {
            // not indexed yet
        }
        const failed = await post(`${RPC}/v1/query/failed-txs`, { address: sender, perPage: 50 });
        const hit = (failed?.results || []).find((f: any) => f.txHash === hash || f.transaction?.txHash === hash);
        if (hit) {
            throw new Error(`tx ${hash} failed: ${JSON.stringify(hit.error)}`);
        }
        await sleep(1000);
    }
    throw new Error(`tx ${hash} not committed within ${timeoutMs}ms`);
}

export function sha256(...parts: Uint8Array[]): Buffer {
    const h = createHash('sha256');
    for (const p of parts) h.update(p);
    return h.digest();
}

export function sha256hex(...parts: Uint8Array[]): string {
    return sha256(...parts).toString('hex');
}

export function u64be(v: bigint): Buffer {
    const b = Buffer.alloc(8);
    b.writeBigUInt64BE(v);
    return b;
}

// rollDie() mirrors the plugin's rejection-sampling die so the client can verify results
export function rollDie(seed: Uint8Array, counter: number, sides: bigint): bigint {
    const limit = (2n ** 32n / sides) * sides;
    for (let i = counter; ; i++) {
        const ctr = Buffer.alloc(4);
        ctr.writeUInt32BE(i >>> 0);
        const x = BigInt(sha256(seed, ctr).readUInt32BE(0));
        if (x < limit) return (x % sides) + 1n;
    }
}

export function sleep(ms: number): Promise<void> {
    return new Promise((r) => setTimeout(r, ms));
}
